package cn.hydrogen.launcher;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.net.*;
import java.security.cert.X509Certificate;
import java.util.*;
import javax.net.ssl.*;

/** Isolated shared-storage fixtures and actual TLS1.2 sockets on API19. */
final class FileCenterFlow {
    private final Instrumentation test;private final Context context;private int passed,failed;
    private final StringBuilder report=new StringBuilder();private File base;private FileCenterActivity activity;private MainActivity launcher;private TransferServer server;
    private SSLSocketFactory clientFactory;private String baseUrl,cookie="";private byte[] certificate;
    private interface Task{void run()throws Exception;}
    FileCenterFlow(Instrumentation test){this.test=test;context=test.getTargetContext();}
    private void require(boolean yes,String why){if(!yes)throw new AssertionError(why);}
    private void check(String title,Task task){try{task.run();passed++;report.append("PASS ");}catch(Throwable error){failed++;report.append("FAIL ").append(error).append(" ");}report.append(title).append('\n');}
    private void denied(Task task)throws Exception{boolean rejected=false;try{task.run();}catch(IOException expected){rejected=true;}require(rejected,"unsafe operation accepted");}
    private void main(Runnable action){Throwable[] error={null};test.runOnMainSync(()->{try{action.run();}catch(Throwable e){error[0]=e;}});test.waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
    private View find(View view,String label){if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()))return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View v=find(((ViewGroup)view).getChildAt(n),label);if(v!=null)return v;}return null;}
    private void click(String label){main(()->{View v=find(activity.getWindow().getDecorView(),label);require(v!=null&&v.isShown(),"missing "+label);v.performClick();});}
    private void capture(String name)throws Exception{Bitmap[] bitmap={null};main(()->{View root=activity.getWindow().getDecorView();bitmap[0]=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap[0]));});try(OutputStream out=new FileOutputStream(new File(context.getFilesDir(),name))){bitmap[0].compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap[0].recycle();}}
    private void write(File file,String value)throws Exception{try(OutputStream out=new FileOutputStream(file)){out.write(value.getBytes("UTF-8"));}}
    private byte[] read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
    private String content(File file)throws Exception{try(InputStream in=new FileInputStream(file)){return new String(read(in),"UTF-8");}}
    private SSLSocket connect(int port)throws Exception{SSLSocket socket=(SSLSocket)clientFactory.createSocket("127.0.0.1",port);socket.setSoTimeout(8000);socket.setEnabledProtocols(new String[]{"TLSv1.2"});socket.startHandshake();certificate=socket.getSession().getPeerCertificates()[0].getEncoded();return socket;}
    private static final class Reply{int status;byte[] body;String headers;String text()throws Exception{return new String(body,"UTF-8");}}
    private Reply request(int port,String method,String path,String length,byte[] body)throws Exception{
        try(SSLSocket socket=connect(port)){OutputStream out=socket.getOutputStream();out.write((method+" "+path+" HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n"+(cookie.isEmpty()?"":"Cookie: "+cookie+"\r\n")+(length==null?"":"Content-Length: "+length+"\r\n")+"\r\n").getBytes("US-ASCII"));if(body!=null)out.write(body);out.flush();InputStream in=socket.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();String whole="";while(!whole.endsWith("\r\n\r\n")){int b=in.read();require(b>=0,"empty response");header.write(b);whole=header.toString("US-ASCII");require(header.size()<16384,"response header too large");}int lengthOfBody=-1;for(String line:whole.split("\r\n"))if(line.toLowerCase(java.util.Locale.US).startsWith("content-length:"))lengthOfBody=Integer.parseInt(line.substring(15).trim());require(lengthOfBody>=0,"missing response length");Reply reply=new Reply();reply.headers=whole;reply.status=Integer.parseInt(whole.split(" ",3)[1]);reply.body=new byte[lengthOfBody];int offset=0;while(offset<reply.body.length){int n=in.read(reply.body,offset,reply.body.length-offset);require(n>0,"truncated response");offset+=n;}return reply;}
    }
    private void login(int port)throws Exception{
        byte[] body=("code="+TransferServer.accessCode(context)).getBytes("US-ASCII");
        Reply reply=request(port,"POST","/login",String.valueOf(body.length),body);require(reply.status==303,"login "+reply.status);
        for(String line:reply.headers.split("\r\n"))if(line.startsWith("Set-Cookie: "))cookie=line.substring(12).split(";",2)[0];
        require(!cookie.isEmpty(),"missing session cookie");
    }
    private Reply get(String relative)throws Exception{return request(server.port(),"GET",baseUrl+relative,null,null);}
    private Reply upload(String name,String value)throws Exception{byte[] bytes=value.getBytes("UTF-8");return request(server.port(),"PUT",baseUrl+"upload?name="+URLEncoder.encode(name,"UTF-8"),String.valueOf(bytes.length),bytes);}
    private void waitState(boolean expected)throws Exception{for(int n=0;n<150;n++){if(FileTransferService.running==expected&&!FileTransferService.starting)return;Thread.sleep(100);}require(false,"service state timeout: "+FileTransferService.state);}
    void run(){
        try{
            require(android.os.Build.VERSION.SDK_INT>=17,"API17+ dedicated fixture required");
            base=new File(StorageFiles.root(context),"WindChaser-Test-"+System.currentTimeMillis()).getCanonicalFile();require(base.mkdir(),"fixture mkdir");
            check("8888 and 123456 defaults migrate once and retain custom ports",()->{
                SharedPreferences prefs=context.getSharedPreferences("transfer-settings",Context.MODE_PRIVATE);Map<String,?> saved=prefs.getAll();
                try{
                    prefs.edit().clear().commit();require(FileTransferService.preferredPort(context)==8888&&TransferServer.accessCode(context).equals("123456"),"fresh defaults");
                    prefs.edit().clear().putInt("port",8443).putString("accessCode","654321").commit();require(FileTransferService.preferredPort(context)==8888&&TransferServer.accessCode(context).equals("123456"),"old defaults not migrated");
                    prefs.edit().putInt("port",9988).commit();require(FileTransferService.preferredPort(context)==9988,"custom port lost");
                    prefs.edit().clear().putInt("port",9989).putString("accessCode","654321").commit();require(FileTransferService.preferredPort(context)==9989&&TransferServer.accessCode(context).equals("123456"),"upgrade custom port lost");
                    require(TransferServer.MAX_UPLOAD==314572800L,"300 MiB limit");
                }finally{SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> e:saved.entrySet()){Object v=e.getValue();if(v instanceof String)edit.putString(e.getKey(),(String)v);else if(v instanceof Integer)edit.putInt(e.getKey(),(Integer)v);else if(v instanceof Boolean)edit.putBoolean(e.getKey(),(Boolean)v);}edit.commit();}
            });
            check("built-in file center is the first application entry",()->{android.content.pm.ResolveInfo first=Ui.apps(context).get(0);require(first.activityInfo.name.equals(FileCenterActivity.class.getName()),"entry missing");});
            check("real launcher item opens the built-in page without resetting its task",()->{
                launcher=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));main(()->launcher.showPage(MainActivity.APPS));Thread.sleep(500);
                Instrumentation.ActivityMonitor monitor=test.addMonitor(FileCenterActivity.class.getName(),null,false);
                try{main(()->{try{Field f=MainActivity.class.getDeclaredField("grid");f.setAccessible(true);GridView grid=(GridView)f.get(launcher);require(((android.content.pm.ResolveInfo)grid.getAdapter().getItem(0)).activityInfo.name.equals(FileCenterActivity.class.getName()),"wrong first app");grid.performItemClick(grid.getChildAt(0),0,0);}catch(Exception e){throw new RuntimeException(e);}});activity=(FileCenterActivity)monitor.waitForActivityWithTimeout(4000);require(activity!=null,"entry did not launch");}finally{test.removeMonitor(monitor);}
            });
            if(activity==null)activity=(FileCenterActivity)test.startActivitySync(new Intent(context,FileCenterActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(200);
            check("entry has two large tiles and the default wallpaper",()->main(()->{View root=activity.getWindow().getDecorView();for(String name:new String[]{"文件管理","文件传输","文件中心默认背景"})require(find(root,name)!=null&&find(root,name).isShown(),"missing "+name);require(find(root,"文件管理").getWidth()>200,"tiles too small");}));capture("v059-files-entry.png");
            check("file management opens shared-storage browser",()->{click("文件管理");Thread.sleep(300);main(()->require(find(activity.getWindow().getDecorView(),"新建文件夹")!=null,"browser not opened"));});capture("v059-files-browser.png");
            File source=new File(base,"中文歌曲.txt");write(source,"WindChaser 文件测试 🎵");File dest=new File(base,"目标");require(dest.mkdir(),"destination mkdir");
            check("rename allows editing extensions and preserves exact contents",()->{File input=new File(base,"改名测试.txt");write(input,"rename-content");File renamed=StorageFiles.rename(base,input,"新名称.lrc");require(!input.exists()&&renamed.getName().equals("新名称.lrc")&&content(renamed).equals("rename-content"),"extension rename failed");require(StorageFiles.mime(renamed).equals("application/octet-stream")||!StorageFiles.mime(renamed).isEmpty(),"mime missing");});
            check("rename refuses collisions, separators, reserved names and root",()->{File input=new File(base,"新名称.lrc"),existing=new File(base,"已存在.lrc");write(existing,"do-not-overwrite");denied(()->StorageFiles.rename(base,input,existing.getName()));for(String invalid:new String[]{"../escape.txt","dir/file.txt","dir\\file.txt","..","",".upload-hidden"})denied(()->StorageFiles.rename(base,input,invalid));denied(()->StorageFiles.rename(base,base,"root-rename"));require(content(existing).equals("do-not-overwrite")&&input.exists(),"rejected rename changed files");});
            check("folder rename retains nested files",()->{File before=new File(base,"目录旧名称");require(before.mkdir(),"folder mkdir");write(new File(before,"子文件.bin"),"nested");File after=StorageFiles.rename(base,before,"目录新名称");require(!before.exists()&&content(new File(after,"子文件.bin")).equals("nested"),"folder rename lost contents");});
            check("browser shows full long filename including extension without ellipsis",()->{
                String name="这是用于验证完整文件名称不会隐藏后缀的很长文件名称-完整版.tar.gz";write(new File(base,name),"visible");main(()->{try{Field folder=FileCenterActivity.class.getDeclaredField("folder");folder.setAccessible(true);folder.set(activity,base);Method build=FileCenterActivity.class.getDeclaredMethod("build");build.setAccessible(true);build.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);main(()->{TextView label=(TextView)find(activity.getWindow().getDecorView(),"完整文件名："+name);require(label!=null&&label.getText().toString().endsWith(name)&&label.getEllipsize()==null&&label.getMaxLines()>1,"filename or extension hidden");});
            });
            check("copy preserves contents and source",()->{File copied=StorageFiles.paste(base,source,dest,false);require(content(copied).equals(content(source))&&source.exists(),"copy differs");});
            check("duplicate paste generates a numbered filename",()->{File copied=StorageFiles.paste(base,source,dest,false);require(copied.getName().equals("中文歌曲 (1).txt"),copied.toString());});
            check("cut moves file and removes source",()->{File moved=StorageFiles.paste(base,source,dest,true);require(!source.exists()&&content(moved).contains("文件测试"),"cut failed");});
            File tree=new File(base,"原文件夹"),nested=new File(tree,"子目录");require(nested.mkdirs(),"tree mkdir");write(new File(nested,"one.bin"),"nested-data");
            check("recursive folder copy and deletion",()->{File copied=StorageFiles.paste(base,tree,dest,false);require(content(new File(copied,"子目录/one.bin")).equals("nested-data"),"recursive copy");StorageFiles.delete(base,copied,0);require(!copied.exists()&&tree.exists(),"recursive delete");});
            check("own descendant, root deletion and outside paths are rejected",()->{denied(()->StorageFiles.paste(base,tree,nested,false));denied(()->StorageFiles.delete(base,base,0));denied(()->StorageFiles.checked(base,new File(base,"../outside")));});
            check("Android storage aliases can delete ordinary directories",()->{File alias=new File(StorageFiles.root(context),base.getName()+"/alias");require(alias.mkdir(),"alias mkdir");write(new File(alias,"data.txt"),"safe");StorageFiles.delete(StorageFiles.root(context),alias,0);require(!alias.exists(),"alias deletion failed");});
            check("manager covers shared roots; private paths are refused",()->{List<File> roots=StorageFiles.roots(context);require(!roots.isEmpty(),"no shared roots");require(StorageFiles.within(StorageFiles.rootFor(context,base),base),"primary missing");for(int x=0;x<roots.size();x++)for(int y=x+1;y<roots.size();y++)require(!StorageFiles.within(roots.get(x),roots.get(y))&&!StorageFiles.within(roots.get(y),roots.get(x)),"duplicate roots");denied(()->StorageFiles.rootFor(context,context.getFilesDir()));});
            check("copy and cut validate independent source and target roots",()->{File left=new File(base,"left"),right=new File(base,"right");require(left.mkdir()&&right.mkdir(),"cross fixtures");File input=new File(left,"cross.txt");write(input,"cross-root");File copied=StorageFiles.paste(left,input,right,right,false);require(content(copied).equals("cross-root")&&input.exists(),"cross copy");File moved=StorageFiles.paste(left,input,right,right,true);require(!input.exists()&&content(moved).equals("cross-root"),"cross cut");denied(()->StorageFiles.paste(left,new File(right,"cross.txt"),right,right,false));});
            File shared=new File(dest,"中文歌曲.txt");Uri uri=LocalFileProvider.uri(context,shared);
            check("Open With content URI reads exact bytes and file metadata",()->{try(InputStream in=context.getContentResolver().openInputStream(uri)){require(new String(read(in),"UTF-8").equals(content(shared)),"provider bytes");}try(android.database.Cursor c=context.getContentResolver().query(uri,null,null,null,null)){require(c!=null&&c.moveToFirst()&&c.getString(0).equals(shared.getName()),"metadata");}});
            check("Open With provider refuses write and app-private files",()->{denied(()->{try(ParcelFileDescriptor ignored=context.getContentResolver().openFileDescriptor(uri,"w")){}});denied(()->{try(InputStream ignored=context.getContentResolver().openInputStream(LocalFileProvider.uri(context,new File(context.getFilesDir(),"secret")))){}});});
            // This trust manager is confined to instrumentation against this local fixture.
            SSLContext tls=SSLContext.getInstance("TLSv1.2");tls.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a){}public void checkServerTrusted(X509Certificate[] c,String a){}}},new java.security.SecureRandom());clientFactory=tls.getSocketFactory();
            File received=new File(base,"HTTPS接收");require(received.mkdir(),"receive mkdir");server=new TransferServer(context,received,()->{});
            check("device-generated certificate and real TLS1.2 HTTPS page",()->{server.start(0);baseUrl="/";require(get("").text().contains("访问码"),"login missing");login(server.port());Reply reply=get("");require(reply.status==200&&reply.text().contains("开始上传")&&reply.text().contains("200")&&reply.text().contains("progress"),"page failed");require(certificate.length>500,"certificate missing");});
            byte[] savedCertificate=certificate;
            check("unauthorized list/upload are refused without cookie",()->{String old=cookie;cookie="";require(get("list").status==403&&upload("unauthorized.txt","x").status==403,"unauthorized access");cookie=old;});
            check("wrong PIN is denied; rate limit rejects repeated guesses",()->{String old=cookie;cookie="";byte[] wrong="code=invalid".getBytes("US-ASCII");for(int i=0;i<5;i++)require(request(server.port(),"POST","/login","12",wrong).status==403,"wrong PIN accepted");require(request(server.port(),"POST","/login","12",wrong).status==429,"no rate limit");cookie=old;});
            check("real UTF-8 named upload and browser list",()->{Reply reply=upload("手机音乐.txt","手机上传内容 🎵");require(reply.status==200&&content(new File(received,"手机音乐.txt")).contains("手机上传内容"),"upload failed");require(get("list").text().contains("手机音乐.txt"),"list missing upload");});
            check("download matches uploaded data",()->require(get("file?name="+URLEncoder.encode("手机音乐.txt","UTF-8")).text().equals("手机上传内容 🎵"),"download differs"));
            check("upload duplicate never overwrites",()->{require(upload("手机音乐.txt","second").status==200,"duplicate upload");require(content(new File(received,"手机音乐 (1).txt")).equals("second")&&content(new File(received,"手机音乐.txt")).contains("手机上传内容"),"duplicate overwrite");});
            check("path traversal, reserved name and oversized upload are rejected",()->{require(upload("../escape.txt","x").status==400,"traversal upload");require(upload(".upload-hidden","x").status==400,"reserved upload");require(get("file?name=..%2Fsecret").status==400,"download traversal");require(request(server.port(),"PUT",baseUrl+"upload?name=huge",String.valueOf(TransferServer.MAX_UPLOAD+1),null).status==413,"upload size");});
            check("missing length refused and default background is a JPEG",()->{require(request(server.port(),"PUT",baseUrl+"upload?name=empty",null,null).status==411,"length missing");byte[] jpg=get("background").body;require(jpg.length>10000&&(jpg[0]&255)==255&&(jpg[1]&255)==216,"background not jpeg");});
            check("interrupted upload removes temporary file",()->{try(SSLSocket socket=connect(server.port())){socket.getOutputStream().write(("PUT "+baseUrl+"upload?name=broken.txt HTTP/1.1\r\nHost: localhost\r\nCookie: "+cookie+"\r\nContent-Length: 100\r\n\r\nabc").getBytes("US-ASCII"));socket.getOutputStream().flush();Thread.sleep(100);}Thread.sleep(700);require(!new File(received,"broken.txt").exists(),"partial visible");for(File f:received.listFiles())require(!f.getName().startsWith(".upload-"),"temp survived");});
            check("close releases port; reopening keeps identity and changes session",()->{int port=server.port();String token=server.token;server.close();server=new TransferServer(context,received,()->{});server.start(port);baseUrl="/";require(get("list").status==403,"old cookie authorized");cookie="";login(server.port());require(get("").status==200&&Arrays.equals(savedCertificate,certificate),"identity not persisted");require(!token.equals(server.token),"session reused");require(request(port,"GET","/t/"+token+"/",null,null).status==404,"old URL routed");});
            check("user-started foreground service survives leaving file screen",()->{context.stopService(new Intent(context,FileTransferService.class));int port;try(ServerSocket free=new ServerSocket(0)){port=free.getLocalPort();}final int selected=port;main(()->context.startService(new Intent(context,FileTransferService.class).putExtra("port",selected)));waitState(true);require(!FileTransferService.addresses().isEmpty(),"no LAN address");for(String address:FileTransferService.addresses())require(!address.contains("/t/")&&address.endsWith(":"+selected),"long address");require(FileTransferService.preferredPort(context)==selected,"port not saved");main(activity::finish);cookie="";login(port);require(request(port,"GET","/list",null,null).status==200,"service stopped on leave");activity=(FileCenterActivity)test.startActivitySync(new Intent(context,FileCenterActivity.class).putExtra("transfer",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(250);main(()->require(find(activity.getWindow().getDecorView(),"关闭传输")!=null,"running toggle missing"));});capture("v059-files-transfer.png");
            check("close HTTPS stops listener and clears session",()->{int port=FileTransferService.port;click("关闭传输");waitState(false);require(FileTransferService.port==0,"port retained");boolean refused=false;try(Socket ignored=new Socket("127.0.0.1",port)){}catch(IOException expected){refused=true;}require(refused,"port still open");});
        }catch(Throwable error){failed++;report.append("FAIL fixture ").append(error).append('\n');}
        finally{if(server!=null)server.close();context.stopService(new Intent(context,FileTransferService.class));if(activity!=null)main(activity::finish);if(launcher!=null)main(launcher::finish);if(base!=null)try{StorageFiles.delete(StorageFiles.root(context),base,0);}catch(Exception error){report.append("cleanup ").append(error).append('\n');}}
        report.append("FILES_RESULT passed=").append(passed).append(" failed=").append(failed).append('\n');Bundle result=new Bundle();result.putString("stream",report.toString());test.finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
